      "legacyIds": [
        "camera:光學效果-optical-effects:鏡頭光斑-lens-flare:9"
      ],
      "zh": "鏡頭光斑 Lens Flare",
      "en": "lens flare artifacts, internal lens reflections, veiling flare, ghosting shapes, streaking flare artifacts from a strong off-axis light source",
      "desc": "強光進入鏡頭後造成內部反射、鬼影、光暈或條狀 flare，重點是鏡頭內部反射瑕疵。",
      "meta": {
        "semantic": {
          "tags": [
            "light_artifact",
            "flare_artifact"
          ]
        }
      }
    },
