      "legacyIds": [
        "camera:光學效果-optical-effects:色差-chromatic-aberration:16"
      ],
      "zh": "色差 Chromatic Aberration",
      "en": "chromatic aberration, subtle RGB edge fringing, lateral color separation along high-contrast edges, minor lens dispersion artifact",
      "desc": "高反差邊緣出現輕微 RGB 分離或彩色邊，重點是鏡片色散造成的光學瑕疵。",
      "meta": {
        "semantic": {
          "tags": [
            "chromatic_aberration"
          ]
        }
      }
    },
